use callisto_model::{Ecosystem, PackageId};
use globset::{Glob, GlobMatcher};

/// A glob pattern for matching package names in `[[package-set]]` blocks.
///
/// Unlike `[[package]]` which uses an exact `PackageId` match,
/// `[[package-set]]` allows a single rule to target many packages at once
/// via a glob (e.g. `"pkg-*"` matches `pkg-a`, `pkg-b`, etc.).
///
/// Ecosystem prefixes in the pattern are respected: `"cargo:pkg-*"` only
/// matches Cargo packages; a bare `"pkg-*"` matches packages in any ecosystem
/// that have a matching name.
#[derive(Clone, Debug)]
pub struct PackagePattern {
    raw: String,
    /// The ecosystem parsed off the front of the pattern (e.g. `cargo` in
    /// `"cargo:pkg-*"`), or `None` for a bare pattern like `"pkg-*"`.
    ecosystem: Option<Ecosystem>,
    /// Compiled from the pattern with any `ecosystem:` prefix stripped.
    matcher: GlobMatcher,
}

impl PackagePattern {
    pub fn parse(s: &str) -> Result<Self, globset::Error> {
        // Try `:` first so `cargo:pkg-*` keeps its existing meaning, then `/`
        // so `cargo/pkg-*` is accepted too, matching `PackageId::parse`'s two
        // qualified forms.
        let (ecosystem, rest) = [':', '/']
            .into_iter()
            .find_map(|sep| {
                let (prefix, rest) = s.split_once(sep)?;
                Ecosystem::from_prefix(prefix).map(|eco| (Some(eco), rest))
            })
            .unwrap_or((None, s));
        let glob = Glob::new(rest)?;
        Ok(Self {
            raw: s.to_string(),
            ecosystem,
            matcher: glob.compile_matcher(),
        })
    }

    /// Returns the ecosystem this pattern was scoped to via an
    /// `ecosystem:` prefix, or `None` for a bare pattern.
    pub fn ecosystem(&self) -> Option<Ecosystem> {
        self.ecosystem
    }

    /// Returns true when the given `PackageId` matches this pattern.
    ///
    /// A bare pattern (no `ecosystem:` prefix) matches any ecosystem, so
    /// `"pkg-*"` matches both `cargo:pkg-a` and `npm:pkg-b`. An
    /// ecosystem-prefixed pattern like `"cargo:pkg-*"` matches only packages
    /// in that ecosystem — `id.ecosystem()` must equal the parsed prefix
    /// before the glob remainder is compared against `id.name()`.
    pub fn matches(&self, id: &PackageId) -> bool {
        self.matches_in_ecosystems(id.name(), id.ecosystem().as_slice())
    }

    /// Like [`Self::matches`], but checks a name against an explicit set of
    /// candidate ecosystems rather than a single `PackageId`.
    ///
    /// This is needed at walk time: discovered package ids are
    /// [`PackageId::Bare`] (no ecosystem attached to the id itself), so the
    /// real ecosystem(s) of the package — sourced from its manifests — must
    /// be supplied explicitly for an ecosystem-prefixed pattern to ever be
    /// able to match.
    pub fn matches_in_ecosystems(&self, name: &str, ecosystems: &[Ecosystem]) -> bool {
        if let Some(want) = self.ecosystem {
            if !ecosystems.contains(&want) {
                return false;
            }
        }
        self.matcher.is_match(name)
    }
        source: SeverityParseError,
    },
}

/// Splits one frontmatter line into its name token and the unparsed
/// remainder (starting at `:`). It unquotes before splitting on `:`, not after.
///
/// **Quoted** name: the closing `"` is located by scanning for the
/// matching delimiter -- never by searching for `:` -- before the
/// remainder is inspected. A name containing `:` itself (Maven's
/// `groupId:artifactId`) is never mis-split, since the separator search
/// only runs on the remainder *after* the name's boundary is resolved by
/// quote-matching.
///
/// **Bare** name: nothing to unquote, so `rsplit_once(':')` applies
/// directly to the whole line.
pub(crate) fn split_name_and_rest(line: &str) -> Result<(NameToken<'_>, &str), LineError> {
    let trimmed = line.trim_start();
    if let Some(after_quote) = trimmed.strip_prefix('"') {
        let end = after_quote.find('"').ok_or(LineError::UnclosedQuotedName)?;
        let name = &after_quote[..end];
        let rest = after_quote[end + 1..].trim_start();
        let rest = rest
            .strip_prefix(':')
            .ok_or_else(|| LineError::AmbiguousNameQuoting { raw: line.to_string() })?;
        Ok((NameToken::Quoted(name.to_string()), rest))
    } else {
        let (name, rest) = trimmed
            .rsplit_once(':')
            .ok_or_else(|| LineError::MissingSeparator { raw: line.to_string() })?;
        Ok((NameToken::Bare(name.trim_end()), rest))
    }
}

/// Parses one frontmatter line (already known non-blank, non-`#`-comment) into an [`Entry`].
pub(crate) fn parse_entry_line(line: &str) -> Result<Entry, LineError> {
    let (token, rest) = split_name_and_rest(line)?;
    let name = match token {
        NameToken::Bare(s) => s.to_string(),
        NameToken::Quoted(s) => s,
    };
    if name.is_empty() {
        return Err(LineError::EmptyName);
    }
    let severity = rest
        .trim()
        .parse::<Severity>()
        .map_err(|source| LineError::InvalidSeverity {
            name: name.clone(),
            source,
        })?;
    Ok(Entry { name, severity })
}

/// Quoted only when necessary on write. Conservative by construction — over-quoting is
/// lossless, under-quoting corrupts output, so every character class that could make a bare
/// scalar ambiguous or YAML-invalid triggers quoting.
pub(crate) fn needs_quoting(name: &str) -> bool {
    let Some(first) = name.chars().next() else {
        return true; // empty name — write_changeset rejects this separately
    };

