    if !args.packages.is_empty() {
        // Non-interactive mode (flags supplied via CLI or agent)
        for pkg_str in args.packages {
            let (name, sev_str) = pkg_str
                .rsplit_once(':')
                .ok_or_else(|| CliError::AddInvalidPackageSpec { spec: pkg_str.clone() })?;

            let severity = parse_severity(sev_str)?;

            // Resolves by any registered native name (not just a package's
            // primary/display name), reporting E102/E103 on a miss or
            // ecosystem-ambiguous bare name.
            let resolved = ws.identity.resolve(name)?;

            entries.push(Entry {
                // Use display_name() so "cargo/foo" is preserved, not just "foo".
                // In a polyglot workspace, the bare name is ambiguous across ecosystems.
                name: resolved.display_name(),
                severity,
            });
        }
    } else if tty::is_interactive() {
        // Interactive 5-step Changesets Wizard (matching @changesets/cli)
        let all_packages: Vec<String> = collect_package_names(ws.graph.packages());

        if all_packages.is_empty() {
            return Err(CliError::AddNoPackagesInWorkspace);
        }

        // Step 1: Package Selection
        prompt_line("Which packages would you like to include in this changeset?");
        let selected_indices = MultiSelect::new().items(&all_packages).interact()?;

        if selected_indices.is_empty() {
            return Err(CliError::AddNoPackagesSelected);
        }

        let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| all_packages[i].clone()).collect();
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(NOTHING_TO_RELEASE)?,
    }
    Ok(())
}

fn parse_selections(packages: &[String]) -> Result<Vec<ReleasePackageId>, CliError> {
    packages.iter().map(|raw| parse_release_selection(raw)).collect()
}

/// Parses one `--package` release selection, accepting `eco:name` as an input
/// alias for the canonical `eco/name` form (one id grammar, everywhere) --
/// `ReleasePackageId::parse`'s own strict `eco/name`-only grammar stays as is
/// for its durable, on-disk encoding (the release-decision file), which this
/// never reads back through.
fn parse_release_selection(raw: &str) -> Result<ReleasePackageId, CliError> {
    match PackageId::parse(raw) {
        Ok(PackageId::Prefixed { ecosystem, name }) => {
            ReleasePackageId::new(ecosystem, name).map_err(|error| CliError::ReleasePackageInvalid {
                raw: raw.to_string(),
                detail: error.to_string(),
            })
        }
        _ => Err(CliError::ReleasePackageInvalid {
            raw: raw.to_string(),
            detail: "expected an ecosystem-qualified package id, e.g. `cargo/pkg` or `cargo:pkg`".to_string(),
        }),
    }
}

/// One-line description of a release operation, shared by both the plain and table renderers.
fn describe_operation(operation: &callisto_model::ReleaseOperation) -> String {
    git: &GitAccess<'_>,
    added: &mut Option<Option<String>>,
    pre_json: &std::path::Path,
    key: &str,
    package: &callisto_model::Package,
    identity: &IdentityIndex,
    rosters: &mut history::Rosters,
) -> bool {
    let held = commit_added(added, git, pre_json).and_then(|rev| match rev {
        Some(rev) => history::may_have_held_name_at(git, rev, key, package, identity, rosters),
        None => Ok(true),
    });
    held.unwrap_or(true)
}

/// Resolves native baselines, attributing historical bare keys at the commit that added `pre.json`.
pub(crate) fn assign_promoted_pre_keys<D: DependencyResolver>(
    git: &GitAccess<'_>,
    graph: &D,
    identity: &IdentityIndex,
    pre_json: &std::path::Path,
    mut state: callisto_model::format::PreState,
    raw_versions: &indexmap::IndexMap<String, String>,
) -> Result<callisto_model::format::PreState, GraphError> {
    let keys: Vec<String> = state.initial_versions.keys().cloned().collect();
    let mut owners = BTreeMap::new();
    let mut rosters = history::Rosters::default();
    let mut added = None;
    for key in &keys {
        if let Some(owner) = graph.packages().find(|p| pre_json_key(&p.id) == *key) {
            if owner.id.ecosystem().is_some()
                || bare_key_may_belong(git, &mut added, pre_json, key, owner, identity, &mut rosters)
            {
                owners.insert(key.clone(), owner);
            } else {
                // Another package's baseline: it must not pin this package's version either.
                state.initial_versions.shift_remove(key);
            }
            continue;
        }
        let same: Vec<&callisto_model::Package> = graph
            .packages()
            .filter(|p| p.id.ecosystem().is_some() && p.id.name() == key.as_str())
            .collect();
        let owner = if same.is_empty() {
            match identity.resolve(key) {
                Ok(id) => {
                    let package = graph.packages().find(|p| p.id == id);
                    package.filter(|package| {
                        PackageId::parse(key).is_ok_and(|parsed| parsed.ecosystem().is_some())
                            || bare_key_may_belong(git, &mut added, pre_json, key, package, identity, &mut rosters)
                    })
                }
                Err(GraphError::UnknownPackage { .. }) => None,
                Err(GraphError::AmbiguousName { candidates, .. }) => {
                    return Err(GraphError::AmbiguousPreJsonKey {
                        key: key.clone(),
                        candidates,
                    });
                }
                Err(error) => return Err(error),
            }
        } else {
            let owner = match commit_added(&mut added, git, pre_json)? {
                Some(rev) => history::sole_owner_at(git, rev, key, &same, identity, &mut rosters)?,
                None => None,
            };
            Some(owner.ok_or_else(|| GraphError::AmbiguousPreJsonKey {
        })
    })
}

/// Resolves a changeset entry's or `--package` argument's parsed `PackageId`
/// against the packages in the graph, through [`IdentityIndex::resolve_id`] --
/// the one selector resolver, not a `PackageId::matches` scan (which treats a
/// Bare query as an ecosystem wildcard and would wrongly let a qualified
/// selector for one ecosystem select a same-named package in another).
///
/// `Ok(None)`: no match (unknown package, reported separately by
/// `validate`). `Ok(Some(pkg))`: unambiguous. `Err(AmbiguousName)`: two or
/// more matches (E103).
pub(crate) fn resolve_target_package<'a>(
    packages: impl Iterator<Item = &'a Package>,
    identity: &IdentityIndex,
    id: &PackageId,
) -> Result<Option<&'a Package>, GraphError> {
    match identity.resolve_id(id) {
        Ok(resolved) => Ok(packages.into_iter().find(|p| p.id == resolved)),
        Err(GraphError::UnknownPackage { .. }) => Ok(None),
        Err(e) => Err(e),
    }
}

