    #[test]
    fn qualified_python_baselines_resolve_to_an_unpromoted_owner() {
        for key in ["pypi/py-lib", "pypi:py-lib"] {
            let temp = workspace(false, ".changeset");
            let root = temp.path();
            run(root, &["pre", "enter", "beta"]);
            let mut state = pre_json(root, ".changeset");
            let baseline = state["initialVersions"]
                .as_object_mut()
                .unwrap()
                .remove("py-lib")
                .unwrap();
            state["initialVersions"][key] = baseline;
            write(root, ".changeset/pre.json", &state.to_string());
            run(
                root,
                &["add", "--package", "py-lib:minor", "--summary", "Qualified baseline"],
            );
            version(root);
            version(root);
            assert_versions(root, "1.3.0b1", "1.0.0", "2.0.0");
            let state = pre_json(root, ".changeset");
            assert_eq!(state["initialVersions"]["py-lib"], "1.2.3");
            assert!(state["initialVersions"].get(key).is_none());
        }
    }

    #[test]
    fn same_named_python_cargo_and_npm_packages_keep_separate_native_baselines() {
        let temp = workspace(true, ".changeset");
        root.join("callisto.toml"),
        r#"
[[fixed-group]]
name = "group-a"
members = ["my-lib"]

[[fixed-group]]
name = "group-b"
members = ["cargo:my-lib"]
"#,
    )
    .unwrap();

    let runner = NoopRunner;
    let locator = IgnoreWalkLocator::new(root);
    let result = Workspace::load(root.to_path_buf(), &locator, &runner);
        r#"
[[fixed-group]]
name = "fixed-a"
members = ["my-lib"]

[[linked-group]]
name = "linked-b"
members = ["cargo:my-lib"]
"#,
    )
    .unwrap();

    let runner = NoopRunner;
    let locator = IgnoreWalkLocator::new(root);
    let result = Workspace::load(root.to_path_buf(), &locator, &runner);

    match result {
        Err(callisto_graph::error::GraphError::ConflictingGroupMembership { groups, .. }) => {
            let names: Vec<String> = groups.iter().map(|g| g.as_str().to_string()).collect();
            assert!(names.contains(&"fixed-a".to_string()));
            assert!(names.contains(&"linked-b".to_string()));
        }
        Err(other) => {
